with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip().upper()

n = len(seq)
stops = ["TAA", "TAG", "TGA"]

findings = []
for strand, s in [("+", seq), ("-", seq.translate(str.maketrans("ACGT","TGCA"))[::-1])]:
    for frame in range(3):
        for i in range(frame, n-2, 3):
            if s[i:i+3] == "ATG":
                # extend to stop in frame
                j = i
                while j + 3 <= n:
                    codon = s[j:j+3]
                    if codon in stops:
                        break
                    j += 3
                length_aa = (j - i) // 3
                findings.append((strand, frame, i+1, j+2, length_aa, j+3-i+1))

findings.sort(key=lambda x: -x[4])
for f in findings[:15]:
    print(f)
