seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip().upper()

length = len(seq)
stops = {"TAA", "TAG", "TGA"}

def revcomp(s):
    return s.translate(str.maketrans("ACGT", "TGCA"))[::-1]

def find_start_of_only_orf(s, frame):
    # longest ORF in this frame: scan codons, find the LAST in-frame stop,
    # ORF = after it up to that stop (or run-off if no in-frame stop upstream)
    i = frame
    orf_start0 = 0
    orf_stop0 = None
    last_stop0 = None
    for i in range(frame, length - 2, 3):
        if s[i:i+3] in stops:
            last_stop0 = i
            orf_start0 = i + 3
    return orf_start0, last_stop0

for strand, s in [("+", seq), ("-", revcomp(seq))]:
    for frame in range(3):
        start0, stop0 = find_start_of_only_orf(s, frame)
        if stop0 is None:
            run = length - start0
            print(f"{strand} frame{frame}: NO in-frame stop; run-off ORF from {start0} len {run} nt "
                  f"({run//3} codons incl. partial stop)")
        else:
            print(f"{strand} frame{frame}: longest ORF {start0} to {stop0+2}, "
                  f"len {stop0 - start0 + 3} nt ({(stop0-start0)//3} aa) startcodon {s[start0:start0+3]}")
        print("  local GC %.3f" % ((s[start0:(stop0+3 if stop0 else length)].count("G")+s[start0:(stop0+3 if stop0 else length)].count("C"))/max(1,(stop0+3 if stop0 else length)-start0)))
