with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip().upper()

length = len(seq)
print("total length:", length)

def revcomp(s):
    return s.translate(str.maketrans("ACGT", "TGCA"))[::-1]

rbseq = revcomp(seq)

for strand, s in [("+", seq), ("-", rbseq)]:
    for frame in range(3):
        # find FIRST in-frame stop searching left-to-right... actually we want longest ORF
        # = segment between two consecutive in-frame stops (or run-off at the end)
        stops_pos = [p for p in range(frame, length-2, 3) if s[p:p+3] in ("TAA","TAG","TGA")]
        # last stop -> ORF from (last_stop+3) to last_stop  (if any stop exists)
        if stops_pos:
            last = stops_pos[-1]
            print(f"{strand} f{frame}: last in-frame stop at {last} ({s[last:last+3]}); "
                  f"ORF after it = {last+3}..{last+2}, len {(length-(last+3))//3+1} codons incl partial")
        else:
            print(f"{strand} f{frame}: NO in-frame stop upstream of position {length}")
